#!/usr/bin/perl
# Makes eggs.html, the public copy of the Guide's Eggs page (her 2026-11-03 pick "also a link she opens"), from index.html's
# own EGGS code, so the two never drift. Run it from the repo root after any change to EGGS (or to the Iron parts it borrows):
#   perl .github/scripts/make-eggs-page.pl
# It reads: index.html (the IRON and EGGS CSS blocks, the EGGS script block, six one-line Iron helpers) and
# .github/scripts/eggs-body.svg (the one body, painted with enough iron: the app draws it live, this page cannot).
# It writes eggs.html: no patient data, no sign-in, nothing saved; out of search results (noindex). The patient copy hides the
# Draft tags, Copy link and the Iron door. Published by .github/workflows/pages.yml.
use strict; use warnings;
sub slurp { open(my $h, "<:raw", $_[0]) or die "cannot read $_[0]\n"; local $/; my $s = <$h>; close $h; $s =~ s/\r\n/\n/g; return $s; }
my $app = slurp("index.html"), my $body = slurp(".github/scripts/eggs-body.svg");
sub block { my ($a, $b) = @_; my $i = index($app, $a); die "start not found: $a\n" if $i < 0; die "start found twice: $a\n" if index($app, $a, $i + 1) >= 0;
  my $j = index($app, $b, $i); die "end not found: $b\n" if $j < 0; return substr($app, $i, $j - $i + length($b)); }
my @lines = split /\n/, $app;   # one pass over the lines: a /^...$/m search of the whole 13 MB file is far too slow
sub line { my ($re) = @_; my @m = grep { /^[ \t]*$re/ } @lines; die "want one line for $re, found " . scalar(@m) . "\n" unless @m == 1; return $m[0] . "\n"; }
my $css = block("/* ============ IRON TEACHING PAGE", "/* ==== end of IRON TEACHING PAGE ==== */") . "\n"
  . block("/* ============ EGGS TEACHING PAGE", "/* ==== end of EGGS TEACHING PAGE ==== */") . "\n";
my $js = join("", map { line($_) } (qr/const phTpReduceMotion = /, qr/const phIrMotion = /, qr/const PH_IR_DROP = /, qr/const PH_IR_O2 = /, qr/const phIrOzO2 = /, qr/const phIrOzMi = /))
  . block("  // ---- EGGS: the Guide's Eggs tab", "  // ---- end of EGGS ----") . "\n";
die "the body figure is missing\n" unless $body =~ /^<svg /;
my $out = <<"HTML";
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex">
<meta name="theme-color" content="#165C74">
<title>Your eggs, oxygen and blood</title>
<link rel="icon" href="icons/favicon-32-v2.png" sizes="32x32">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght\@400;500;600;700&display=swap">
<!-- MADE by .github/scripts/make-eggs-page.pl from index.html's EGGS code. Do not edit this file: change EGGS, then re-run it. -->
<style>
html, body { margin: 0; background: #F5F8F9; color: #141F23; }
body { font-family: 'Inter', -apple-system, 'Segoe UI', sans-serif; font-size: 14px; line-height: 1.45; }
* { box-sizing: border-box; }
button { font: inherit; color: inherit; }
.wrap { max-width: 1180px; margin: 0 auto; padding-block: max(12px, env(safe-area-inset-top, 0px)) 28px;
  padding-left: max(14px, env(safe-area-inset-left, 0px)); padding-right: max(14px, env(safe-area-inset-right, 0px)); }
.brand { margin: 2px 2px 10px; font-size: 11px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: #8A6D1A; }
#pharmacyPage { --font-body: 'Inter', -apple-system, 'Segoe UI', sans-serif; --ph-herb: #165C74; --ph-herb-tint: #EDF5F8; --ph-ink: #141F23; --ph-soft: #4A575B;
  --ph-line: #D3DEE2; --ph-white: #FFFFFF; --ph-gold: #D9AE47; --ph-gold-deep: #8A6D1A; --ph-gold-tint: #FFFBE2;
  --fs-10: 10px; --fs-10-5: 10.5px; --fs-11: 11px; --fs-11-5: 11.5px; --fs-12: 12px; --fs-12-5: 12.5px; --fs-13: 13px; --fs-13-5: 13.5px; --fs-14: 14px;
  --fs-15: 15px; --fs-16: 16px; --fs-18: 18px; --fs-20: 20px; --fs-22: 22px; --fs-24: 24px; --fs-26: 26px; --fs-28: 28px; color: var(--ph-ink); }
/* the band and its white boxes (the app's shared band rule) */
#pharmacyPage .ph-ir { padding: 12px; border-radius: 10px; background: var(--ph-herb-tint); }
#pharmacyPage .ph-ir .ir-box { padding: 12px 14px 14px; border-radius: 10px; background: var(--ph-white); }
$css
/* the patient's copy: no Draft tags, no Copy link, no door to the clinic's Iron page; the body pale with less blood flow */
#pharmacyPage :is(.ir-draft, [data-eg-link], [data-ir-open]) { display: none !important; }
#pharmacyPage .lens.body.pale svg { filter: saturate(.3) brightness(1.06); }
</style>
</head>
<body>
<div class="wrap"><div class="brand">Linh Chinese Medicine</div><div id="pharmacyPage"><div id="phGdHost"></div></div></div>
<script type="text/x-svg" id="egbody">$body</script>
<script>
// the few app helpers the page needs; the body is a still copy (pale = less blood flow)
const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const PH_IR_OK = { lv: 1 }, PH_IR_LOW = { lv: .2 };
const phMbdSvg = () => document.getElementById("egbody").textContent;
function phIrBodyEase(host, a, b) { if (host) host.classList.toggle("pale", b === PH_IR_LOW); }
const phCkCopy = () => {};
$js
document.addEventListener("click", phEgClick);
document.getElementById("phGdHost").innerHTML = phEgHtml();
phEgMount();
</script>
</body>
</html>
HTML
$out =~ s/\r\n/\n/g;   # this script may be checked out with CRLF; the page is LF throughout
open(my $oh, ">:raw", "eggs.html") or die; print $oh $out; close $oh;
print "eggs.html: " . length($out) . " bytes\n";
